import { PAGE_STYLE_TYPES, type AlbumConfig, type PageStyleType } from "../types";

/**
 * The decorative treatment the greeting pages should wear.
 *
 * Syncing borrows the cover's style so the whole album reads as one object.
 * The cover has one style pages cannot wear — a full-bleed hero photo, which a
 * page has nothing to fill itself with — so that case lands on the plain
 * treatment and the album's own backdrop carries the look instead.
 */
export function resolvePageStyle(album: AlbumConfig): PageStyleType {
  const chosen = album.syncPageStyleWithCover ? album.coverStyle : album.pageStyle;
  return isPageStyle(chosen) ? chosen : "MINIMAL";
}

/**
 * The style classes a page surface wears. `custom-bg` suppresses the styles
 * that paint a material — aged paper, foil — because a page that was given its
 * own backdrop asked for that backdrop to be seen; its frame still draws.
 */
export function pageStyleClass(album: AlbumConfig, hasOwnBackground: boolean) {
  const slug = resolvePageStyle(album).toLowerCase().replace(/_/g, "-");
  return `ae-page--style-${slug}${hasOwnBackground ? " ae-page--custom-bg" : ""}`;
}

function isPageStyle(value: unknown): value is PageStyleType {
  return PAGE_STYLE_TYPES.includes(value as PageStyleType);
}
